<script setup lang="ts">
import DemoBar from './components/DemoBar.vue';import {isDemo} from './demo';
import {computed,ref} from 'vue';import NotificationBell from './components/NotificationBell.vue';import {useRouter} from 'vue-router';import {useAuth} from './stores/auth';import {LayoutDashboard,Building2,ClipboardList,FolderOpen,CalendarDays,Wallet,FileText,MessagesSquare,Settings,LogOut,ArrowUpRight,Menu} from 'lucide-vue-next';import {errorText} from './api';
const auth=useAuth();const router=useRouter();const menu=ref(false);const error=ref('');const items=computed(()=>[{path:'/',label:auth.staff?'Resumen':'Mi portal',icon:LayoutDashboard},{path:'/companies',label:'Empresas',icon:Building2},{path:'/works',label:'Trabajos',icon:ClipboardList},{path:'/documents',label:auth.staff?'Documentos':'Mis pendientes',icon:FolderOpen},...(auth.staff?[{path:'/tasks',label:'Agenda y tareas',icon:CalendarDays}]:[]),{path:'/billing',label:'Honorarios',icon:Wallet},{path:'/reports',label:'Informes',icon:FileText},{path:'/conversations',label:'Consultas',icon:MessagesSquare},...(auth.admin?[{path:'/settings',label:'Configuración',icon:Settings}]:[])]);
async function logout(){try{await auth.logout();router.push('/login');}catch(e){error.value=errorText(e);}}
async function changeStudy(e:Event){try{await auth.switchStudy(Number((e.target as HTMLSelectElement).value));window.location.assign('/');}catch(e){error.value=errorText(e);}}
</script>
<template><RouterView v-if="!auth.user"/><div v-else class="app-shell"><aside class="sidebar" :class="{expanded:menu}"><RouterLink to="/" class="brand">express<span>conta</span><b>.</b></RouterLink><div class="brand-caption">EL ESTUDIO, EN ORDEN</div><button class="mobile-menu" @click="menu=!menu" :aria-expanded="menu"><Menu :size="18"/> Menú</button><nav aria-label="Navegación principal"><RouterLink v-for="item in items" :key="item.path" :to="item.path" :class="{active:router.currentRoute.value.path===item.path}" @click="menu=false"><component :is="item.icon" :size="18" stroke-width="1.7"/>{{item.label}}</RouterLink></nav><div class="sidebar-bottom"><span class="avatar">{{auth.user.name.split(' ').map((x:string)=>x[0]).slice(0,2).join('')}}</span><div><strong>{{auth.user.name}}</strong><small>{{{admin:'Administración',accountant:'Contabilidad',reviewer:'Revisión',client:'Cliente'}[auth.role]}}</small></div><button @click="logout" class="logout" aria-label="Cerrar sesión"><LogOut :size="17"/></button></div></aside><div class="workspace"><header class="topbar"><div class="study-name">{{auth.study?.name}} <ArrowUpRight :size="14"/></div><label v-if="auth.studies.length>1" class="study-select">Estudio<select :value="auth.study_id" @change="changeStudy"><option v-for="s in auth.studies" :value="s.id" :key="s.id">{{s.name}}</option></select></label><NotificationBell :key="auth.role"/><span class="top-label">{{auth.staff?'Espacio del estudio':'Portal del cliente'}} <span class="connection-dot"></span></span></header><DemoBar v-if="isDemo"/><div v-if="error" role="alert" class="error">{{error}}</div><main class="content"><RouterView :key="String(auth.study_id)+auth.role"/></main><footer class="app-footer"><span>ExpressConta · Gestión del estudio</span><span>America/Santiago · CLP</span></footer></div></div></template>
